package com.stark.automation.listeners;
import com.stark.automation.core.driver.DriverFactory; import com.stark.automation.utils.ScreenshotCapture; import io.qameta.allure.Allure; import java.io.ByteArrayInputStream; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.testng.*;
public class TestListener implements ITestListener { private static final Logger LOG = LoggerFactory.getLogger(TestListener.class); @Override public void onTestStart(ITestResult result) { LOG.info("Starting test: {}", result.getMethod().getMethodName()); } @Override public void onTestSuccess(ITestResult result) { LOG.info("Passed test: {}", result.getMethod().getMethodName()); } @Override public void onTestFailure(ITestResult result) { LOG.error("Failed test: {}", result.getMethod().getMethodName(), result.getThrowable()); try { if (DriverFactory.getDriver() != null) { byte[] screenshot = ScreenshotCapture.capture(result.getMethod().getMethodName()); if (screenshot.length > 0) Allure.addAttachment("Failure screenshot", "image/png", new ByteArrayInputStream(screenshot), ".png"); } } catch (Exception ignored) { LOG.debug("Could not capture failure screenshot"); } } }
